served_parcels = (
    developable.loc[served_rows].copy()
    if len(served_rows) > 0
    else developable.iloc[:0].copy()
)

if len(nearby_buildings) > 0 and len(served_parcels) > 0:
    occupied = gpd.overlay(
        served_parcels[["parcel_id", "geometry"]],
        nearby_buildings[["building_id", "geometry"]],
        how="intersection",
    )
    occupied = occupied[occupied.geometry.geom_type.isin(POLYGONAL_TYPES)].copy()
else:
    occupied = gpd.GeoDataFrame({"geometry": []}, geometry="geometry", crs=parcels.crs)

if len(blocks) > 0 and len(catchments) > 0:
    coverage = gpd.overlay(
        blocks[["parcel_id", "district", "geometry"]],
        catchments[["station_id", "geometry"]],
        how="intersection",
    )
    coverage = coverage[coverage.geometry.geom_type.isin(POLYGONAL_TYPES)].copy()
else:
    coverage = gpd.GeoDataFrame({"geometry": []}, geometry="geometry", crs=blocks.crs)

if len(coverage) > 0:
    coverage["covered_area"] = coverage.geometry.area
    district_coverage = coverage.dissolve(
        by="district",
        aggfunc={"parcel_id": "count", "covered_area": "sum"},
    ).reset_index()
    district_coverage["geometry"] = district_coverage.geometry.convex_hull
else:
    district_coverage = coverage.copy()

if len(filtered) > 0:
    risk_zones = filtered.copy()
    risk_zones["geometry"] = filtered.geometry.centroid.buffer(50.0)
else:
    risk_zones = filtered.copy()

if len(parcels) > 0 and len(riparian) > 0:
    corridor_parcels = gpd.clip(parcels, riparian)
    corridor_parcels = corridor_parcels[
        corridor_parcels.geometry.geom_type.isin(POLYGONAL_TYPES)
    ].copy()
else:
    corridor_parcels = gpd.GeoDataFrame({"geometry": []}, geometry="geometry", crs=parcels.crs)

if len(corridor_parcels) > 0:
    habitat_hits = gpd.sjoin(
        corridor_parcels,
        habitat[["species", "geometry"]],
        predicate="intersects",
    )
    habitat_parcels = corridor_parcels.loc[habitat_hits.index.unique()].copy()
else:
    habitat_parcels = corridor_parcels.copy()

if len(habitat_parcels) > 0:
    protected_hits = gpd.sjoin(
        habitat_parcels,
        protected[["exclusion_type", "geometry"]],
        predicate="intersects",
    )
    impacted = habitat_parcels.loc[protected_hits.index.unique()].copy()
else:
    impacted = habitat_parcels.copy()

if len(impacted) > 0:
    impacted["impacted_area"] = impacted.geometry.area
    summary = impacted.dissolve(
        by="reporting_region",
        aggfunc={"parcel_id": "count", "impacted_area": "sum"},
    ).reset_index()
else:
    summary = impacted.copy()

if len(candidate_parcels) > 0:
    exposure = gpd.overlay(
        candidate_parcels[["parcel_id", "parcel_area", "geometry"]],
        flood_zones[["zone_id", "geometry"]],
        how="intersection",
    )
    exposure = exposure[exposure.geometry.geom_type.isin(POLYGONAL_TYPES)].copy()
else:
    exposure = gpd.GeoDataFrame({"geometry": []}, geometry="geometry", crs=parcels.crs)

if len(competitors) > 0 and len(near_roads) > 0:
    safe_sites = spatial_antijoin(
        near_roads,
        competitors,
        predicate="intersects",
    )
else:
    safe_sites = near_roads.copy()

if len(safe_sites) > 0:
    safe_sites["submarket"] = (safe_sites["parcel_id"] // 250).astype(str)
    trade_areas = safe_sites.dissolve(
        by="submarket",
        aggfunc={"parcel_id": "count"},
    ).reset_index()
else:
    trade_areas = safe_sites.copy()

if len(clipped) > 0:
    buffered_veg = clipped.copy()
    buffered_veg["geometry"] = clipped.geometry.centroid.buffer(1.0)
    joined = gpd.sjoin(poles, buffered_veg[["geometry"]], predicate="within")
else:
    joined = poles.iloc[:0]
